// Project-level type augmentations for Next.js 16.
//
// Framework types (next-env.d.ts, .next/types/routes.d.ts, and the global
// PageProps / LayoutProps / RouteContext helpers) are generated by
// `next dev`, `next build`, or `next typegen` and are intentionally not
// committed. Declare only project-specific types here.

declare namespace NodeJS {
  interface ProcessEnv {
    /** Base URL of the Go backend API, e.g. http://localhost:8080 */
    readonly NEXT_PUBLIC_API_URL?: string;
    /** WebSocket endpoint for realtime updates. */
    readonly NEXT_PUBLIC_WS_URL?: string;
    /** Public origin of the frontend; used as metadataBase for SEO/Open Graph URLs. */
    readonly NEXT_PUBLIC_SITE_URL?: string;
    /** Comma-separated extra hostnames allowed by next/image. */
    readonly NEXT_PUBLIC_ADDITIONAL_IMAGE_DOMAINS?: string;
    readonly NEXT_PUBLIC_STELLAR_NETWORK?: string;
    readonly NEXT_PUBLIC_STELLAR_HORIZON_URL?: string;
  }
}
